package ibcpacket

import (
	"encoding/hex"
	"testing"
)

// The send_packet event of gno-realms' z5e_transfer_to_ethereum filetest, as
// the relayer's ibc/packet_test.go decodes it.
const z5ePacket = ""

func TestDecodeProtoVector(t *testing.T) {
	bz, _ := hex.DecodeString(z5ePacket)
	p, err := DecodeProto(bz)
	if err != nil {
		t.Fatal(err)
	}
	if p.Sequence != 1 || p.SourceClient != "ethereum-1" || p.DestinationClient != "client-0" || p.TimeoutTimestamp != 1234571490 {
		t.Fatalf("header %+v", p)
	}
	if len(p.Payloads) != 1 {
		t.Fatalf("payloads %d", len(p.Payloads))
	}
	pl := p.Payloads[0]
	if pl.SourcePort != "transfer" || pl.DestinationPort != "transfer" || pl.Version != "ics20-1" || pl.Encoding != "application/x-solidity-abi" || len(pl.Value) != 480 {
		t.Fatalf("payload %+v", pl)
	}
	// Re-encoding gives the vector back.
	if hex.EncodeToString(EncodeProto(p)) != z5ePacket {
		t.Fatal("encode/decode round trip differs from the vector")
	}
	if _, err := DecodeProto(bz[:len(bz)-5]); err == nil {
		t.Fatal("truncated accepted")
	}
}
